update public.academy_modules set learning_objectives = array['Understand professional recruiter communication principles.', 'Conduct structured and professional candidate screening calls.', 'Ask relevant questions based on job requirements.', 'Evaluate candidate qualifications, skills and experience against requirements.', 'Distinguish between requirement matches, gaps and information requiring clarification.', 'Handle candidate questions and objections professionally.', 'Coordinate interviews accurately and professionally.', 'Communicate interview updates and follow-ups clearly.', 'Maintain accurate candidate screening and interview information.', 'Complete an end-to-end screening and interview coordination workflow.']::text[] where module_number = 4;
insert into public.lessons (module_id, sort_order, title, description, content_type, estimated_minutes, is_required, status, content)
select id, 1, 'Professional Candidate Communication', 'Respectful, clear and trustworthy communication with every candidate.', 'text', 15, true, 'active', '{"blocks": [{"type": "h", "text": "Communication fundamentals"}, {"type": "p", "text": "Every call, message and email shapes how candidates see you and the company. Professional communication is clear, respectful, accurate, concise and focused on the requirement."}, {"type": "terms", "items": [{"term": "Respectful interaction", "definition": "Greet by name, ask if it is a good time, thank the candidate for their time."}, {"term": "Clear and simple language", "definition": "Short sentences; explain terms like CTC or notice buyout if needed."}, {"term": "Professional tone", "definition": "Polite and calm, even when the candidate is not interested."}, {"term": "Active listening", "definition": "Let the candidate finish, then summarise what you heard."}, {"term": "Relevant questions", "definition": "Ask only what the requirement needs."}, {"term": "Avoid confusing language", "definition": "No jargon, slang or internal abbreviations."}, {"term": "Avoid assumptions", "definition": "Ask instead of guessing location, salary or interest."}, {"term": "Maintain trust", "definition": "Share only confirmed information; do what you said you would."}, {"term": "Professionalism", "definition": "Be on time for calls, keep records accurate, protect candidate data."}]}, {"type": "h", "text": "Good vs poor communication (fictional example)"}, {"type": "compare", "title": "Opening a call with Ms. Kavya R. about a Customer Support role", "good": "\"Good afternoon, Kavya. This is Arjun from E2E Procurement. I''m calling about a Customer Support Executive opening in Bengaluru that matches your profile. Is this a good time to speak for five minutes?\"", "bad": "\"Hi, job hai, interested? Salary achha hai, kal interview aa jao.\"", "goodLabel": "Good", "badLabel": "Poor"}, {"type": "h", "text": "Why the good example is better"}, {"type": "list", "items": ["Introduces the recruiter and company, so the candidate knows who is calling.", "States the role and location clearly.", "Asks for permission and sets a time expectation.", "Makes no promises about salary or selection.", "The poor example is vague, informal, pressures the candidate and implies unverified salary."]}, {"type": "callout", "text": "Candidates remember how they were treated, even when they are not selected. That reputation affects future sourcing."}]}'::jsonb from public.academy_modules where module_number = 4
