select id, 2, 'Recruiter Screening Calls', 'Preparing for, conducting and closing a structured screening call.', 'text', 18, true, 'active', '{"blocks": [{"type": "h", "text": "Purpose of a screening call"}, {"type": "p", "text": "A screening call confirms whether the candidate meets the requirement and is genuinely interested, before their profile goes to the hiring manager."}, {"type": "h", "text": "Before the call"}, {"type": "list", "items": ["Re-read the JD and your candidate profile notes.", "Review the candidate''s CV and source record.", "List what to confirm and what is still missing.", "Have the approved role details ready: location, shift, CTC range, process."]}, {"type": "h", "text": "Fictional screening-call structure"}, {"type": "steps", "items": [{"title": "Greeting", "text": "\"Good morning, may I speak with Mr. Rahul Menon?\""}, {"title": "Introduction", "text": "Your name, company and reason for calling."}, {"title": "Candidate availability", "text": "\"Is this a good time to talk for about ten minutes?\" If not, fix a call-back time."}, {"title": "Role explanation", "text": "Title, key responsibilities, location, work mode, shift — confirmed facts only."}, {"title": "Basic screening", "text": "Experience, skills, qualification, location, notice period, expectations."}, {"title": "Candidate questions", "text": "Answer what you know; note anything you need to verify."}, {"title": "Next steps", "text": "Explain what happens next and approximate timelines."}, {"title": "Professional closing", "text": "Thank the candidate and confirm how you will contact them."}]}, {"type": "h", "text": "During the call"}, {"type": "list", "items": ["Listen carefully; do not interrupt.", "Record answers accurately as you go.", "Repeat key facts back: \"So your notice period is 30 days, negotiable to 15?\""]}, {"type": "h", "text": "After the call"}, {"type": "p", "text": "Update the candidate record the same day: response, confirmed details, gaps, next action and date."}, {"type": "callout", "text": "This lesson is training only — the platform does not place calls or send messages."}]}'::jsonb from public.academy_modules where module_number = 4
