select id, 3, 'Candidate Screening Questions', 'Asking relevant, professional questions linked to the requirement.', 'scenario', 18, true, 'active', '{"blocks": [{"type": "h", "text": "Question areas"}, {"type": "terms", "items": [{"term": "Qualification", "definition": "\"What is your highest qualification and year of completion?\""}, {"term": "Skills", "definition": "\"Which version of Tally do you use, and for which tasks?\""}, {"term": "Experience", "definition": "\"How many years have you worked specifically in accounts payable?\""}, {"term": "Location / work mode", "definition": "\"The role is work from office in Guindy. Is that comfortable for you?\""}, {"term": "Shift / availability", "definition": "\"The shift is rotational, including nights. Are you able to work this?\""}, {"term": "Notice period", "definition": "\"What is your notice period, and is early release possible?\""}, {"term": "Salary expectation", "definition": "\"What are your expectations for this role?\" — share the approved range only if authorised."}, {"term": "Missing information", "definition": "\"Your CV does not mention GST filing — have you handled it?\""}]}, {"type": "h", "text": "Avoid irrelevant or inappropriate questions"}, {"type": "p", "text": "Never ask about religion, caste, marital status, pregnancy or family plans, age (beyond legal eligibility), or anything unrelated to the job."}, {"type": "h", "text": "Scenario (fictional)"}, {"type": "example", "title": "Role: Accounts Executive, Chennai, B.Com, 2–4 yrs AP, Tally Prime + GST mandatory", "text": "Candidate: Ms. Divya S., 3 years at a fictional trading firm. Which questions should the recruiter ask?"}, {"type": "answer", "title": "Relevant vs not relevant", "items": [{"term": "Relevant", "definition": "\"Do you prepare GST returns yourself?\" — verifies a mandatory skill."}, {"term": "Relevant", "definition": "\"How many vendor invoices do you process monthly?\" — checks depth of AP experience."}, {"term": "Relevant", "definition": "\"Can you commute to Guindy daily for a 9:30 start?\" — location/work mode."}, {"term": "Not relevant", "definition": "\"Are you planning to get married soon?\" — personal, not job-related, inappropriate."}, {"term": "Not relevant", "definition": "\"Which community are you from?\" — discriminatory and unacceptable."}, {"term": "Needs care", "definition": "\"What is your current CTC?\" — ask only where policy and law allow; expected CTC is usually sufficient."}]}]}'::jsonb from public.academy_modules where module_number = 4
