select id, 4, 'Candidate Evaluation and Screening Decisions', 'Objective, evidence-based screening decisions against the JD.', 'text', 17, true, 'active', '{"blocks": [{"type": "h", "text": "Decision categories"}, {"type": "terms", "items": [{"term": "MATCH", "definition": "Candidate meets the relevant requirement."}, {"term": "GAP", "definition": "Candidate does not currently meet the requirement."}, {"term": "CLARIFICATION REQUIRED", "definition": "Information is missing or unclear."}, {"term": "NOT SUITABLE", "definition": "Candidate clearly does not meet an essential requirement."}]}, {"type": "h", "text": "Evaluation framework"}, {"type": "p", "text": "For each requirement record: Requirement → Candidate information → Match / Gap → Evidence → Screening decision."}, {"type": "example", "title": "Fictional example — Mr. Imran K., Java Developer, Pune", "text": "Java + Spring Boot (mandatory): 4 yrs, described current project APIs → MATCH. Location Pune: lives in Mumbai, will relocate in 30 days → CLARIFICATION REQUIRED (confirm with hiring manager). AWS (preferred): none → GAP, not blocking. Notice ≤45 days: 60 days, buyout possible → CLARIFICATION REQUIRED. Decision: Shortlist subject to hiring-manager approval on relocation and notice."}, {"type": "h", "text": "Outcomes"}, {"type": "terms", "items": [{"term": "Shortlisted", "definition": "All mandatory requirements matched; preferred gaps noted."}, {"term": "Needs clarification", "definition": "One or more mandatory items unclear; resolve before submitting."}, {"term": "Not suitable", "definition": "An essential requirement is clearly not met. Inform the candidate politely."}]}, {"type": "h", "text": "Keep decisions objective"}, {"type": "p", "text": "Decide only on job-related evidence. Never let appearance, age assumptions, gender stereotypes, religion, caste, personal relationships or other unrelated characteristics influence a decision."}, {"type": "callout", "text": "Write the evidence, not your opinion: ''3 years AP at ABC Traders, prepares GSTR-1 monthly'' — not ''seems good''."}]}'::jsonb from public.academy_modules where module_number = 4
