select id, 5, 'Handling Candidate Objections and Questions', 'Responding professionally, and verifying instead of guessing.', 'scenario', 16, true, 'active', '{"blocks": [{"type": "h", "text": "Common questions and professional responses (fictional)"}, {"type": "terms", "items": [{"term": "Role", "definition": "\"What exactly will I do?\" → Explain the confirmed responsibilities from the JD."}, {"term": "Salary", "definition": "\"Can you guarantee 8 LPA?\" → \"The approved range is up to 7 LPA. I''ll share your expectation, but the final offer is decided by the company.\""}, {"term": "Location", "definition": "\"Can I work from Thane instead?\" → \"The role is based in Andheri. I''ll check whether any flexibility exists and get back to you by tomorrow.\""}, {"term": "Shift", "definition": "\"Will nights be permanent?\" → Share the confirmed rotation; verify if unsure."}, {"term": "Work mode", "definition": "\"Is it hybrid?\" → State what the JD says; don''t guess the number of office days."}, {"term": "Notice period", "definition": "\"I have 90 days.\" → Record it and check whether the client can accept it."}, {"term": "Interview", "definition": "\"How many rounds?\" → Share the confirmed process only."}, {"term": "Next steps", "definition": "\"When will I hear back?\" → Give a realistic timeline and follow up as promised."}]}, {"type": "h", "text": "Never"}, {"type": "list", "items": ["Make false promises or guarantee selection.", "Invent salary figures or benefits.", "Share unverified company information.", "Argue with or pressure a candidate.", "Use disrespectful language."]}, {"type": "h", "text": "Scenario"}, {"type": "example", "title": "Mr. Suresh P. says: \"Another consultant said this company gives 40% hike. Is that true?\"", "text": "Professional response: \"I can''t confirm that. The approved range for this role is 4.5–5.5 LPA. If your expectation is higher, I''ll share it with the hiring team, and they will decide.\""}, {"type": "callout", "text": "When in doubt, say \"Let me verify that and get back to you\" — and record a follow-up so you actually do."}]}'::jsonb from public.academy_modules where module_number = 4
