select id, 6, 'Interview Scheduling and Coordination', 'Practice: schedule, confirm and track fictional interviews accurately.', 'practice', 20, true, 'active', '{"blocks": [{"type": "h", "text": "Scheduling steps"}, {"type": "steps", "items": [{"title": "Collect availability", "text": "Ask for two or three suitable slots."}, {"title": "Confirm date and time", "text": "Match with the interviewer''s calendar."}, {"title": "Interview mode", "text": "In person, video or phone."}, {"title": "Interviewer details", "text": "Name and designation, if approved to share."}, {"title": "Location / meeting info", "text": "Address and contact person, or the meeting link."}, {"title": "Send and record confirmation", "text": "Written confirmation through the approved channel; log it."}, {"title": "Candidate acknowledgement", "text": "Get a clear ''confirmed'' from the candidate."}, {"title": "Reminders", "text": "Day before and two hours before."}, {"title": "Rescheduling", "text": "Offer new slots promptly; update the record."}, {"title": "Cancellation", "text": "Inform both sides quickly, with a reason where appropriate."}]}, {"type": "h", "text": "Exercise (fictional — no real calendar or invitations)"}, {"type": "example", "title": "Situation", "text": "Ms. Anjali T. (Inside Sales Executive) is free Wed 11 am or Thu 3 pm. The interviewer, Mr. Vikram (Sales Manager), is free only Thu 3–5 pm, video. Anjali confirms by message. On Wednesday evening she asks to move to Friday because of a family emergency; Vikram can do Friday 12 pm."}, {"type": "p", "text": "Fill these fields for the final schedule: Candidate, Role, Interview Date, Interview Time, Interview Mode, Interviewer, Confirmation Status, Candidate Response, Next Action."}, {"type": "answer", "title": "Model schedule record", "items": [{"term": "Candidate", "definition": "Anjali T."}, {"term": "Role", "definition": "Inside Sales Executive"}, {"term": "Interview Date", "definition": "Friday (rescheduled from Thursday)"}, {"term": "Interview Time", "definition": "12:00 pm"}, {"term": "Interview Mode", "definition": "Video"}, {"term": "Interviewer", "definition": "Vikram — Sales Manager"}, {"term": "Confirmation Status", "definition": "Rescheduled and reconfirmed by both"}, {"term": "Candidate Response", "definition": "Requested reschedule (personal reason); confirmed Friday 12 pm"}, {"term": "Next Action", "definition": "Send updated link; reminder Friday 10 am; record outcome after interview"}]}, {"type": "callout", "text": "Log every change with date and time. The interview record is the single source of truth for everyone involved."}]}'::jsonb from public.academy_modules where module_number = 4
