select id, 7, 'Interview Follow-Up and Candidate Status Communication', 'Keeping candidates informed after interviews without promising outcomes.', 'text', 15, true, 'active', '{"blocks": [{"type": "h", "text": "After the interview"}, {"type": "list", "items": ["Call the candidate the same day: how did it go, any concerns?", "Request feedback from the interviewer within the agreed time.", "Update the record with both sides'' feedback."]}, {"type": "h", "text": "Status communication"}, {"type": "terms", "items": [{"term": "Pending feedback", "definition": "\"The panel is still reviewing. I expect an update by Thursday and will call you then.\""}, {"term": "Feedback follow-up", "definition": "Chase the interviewer politely; tell the candidate if timelines move."}, {"term": "Selected", "definition": "Share only after authorised confirmation: \"I''m pleased to inform you the team has decided to move forward. HR will share offer details.\""}, {"term": "Rejected", "definition": "\"Thank you for your time. The team has decided not to proceed for this role. I''ll keep your profile for suitable openings.\""}, {"term": "Offer stage", "definition": "Explain next steps and documents; do not quote numbers until the offer is approved."}]}, {"type": "compare", "title": "Before confirmation", "good": "\"Feedback is awaited — I''ll update you as soon as I hear.\"", "bad": "\"Don''t worry, you''re selected for sure.\"", "goodLabel": "Say", "badLabel": "Never say"}, {"type": "h", "text": "Document and close professionally"}, {"type": "p", "text": "Record every status update with date and time. Close every candidate journey — selected or not — with a clear, respectful final message."}, {"type": "callout", "text": "Never promise an outcome before it is confirmed by the authorised person."}]}'::jsonb from public.academy_modules where module_number = 4
