select id, 8, 'Complete Candidate Screening & Interview Workflow', 'Practice: work through an end-to-end fictional scenario and make decisions.', 'practice', 21, true, 'active', '{"blocks": [{"type": "h", "text": "Fictional scenario"}, {"type": "example", "title": "JD requirement", "text": "Role: Procurement Executive, fictional client ''Southline Components'', Chennai (Ambattur), WFO, general shift, Mon–Sat. Mandatory: 2–5 yrs purchase in manufacturing, SAP MM. Preferred: Tamil. CTC up to 5.5 LPA. Notice ≤ 30 days."}, {"type": "example", "title": "Candidate information", "text": "Mr. Karthik V. (fictional), 3.5 yrs Purchase Executive at a fictional auto-parts maker, SAP MM daily (PO creation, vendor master), lives in Avadi, Tamil and English, expects 5.8 LPA, notice 45 days with possible early release."}, {"type": "h", "text": "Work through each stage"}, {"type": "list", "items": ["Screening — what will you confirm on the call?", "Screening decision — Match / Gap / Clarification for each requirement.", "Candidate communication — how do you handle the CTC and notice gaps?", "Interview scheduling — what do you record?", "Interview follow-up — what do you say while feedback is pending?", "Status update and next action."]}, {"type": "answer", "title": "Model Evaluation", "items": [{"term": "Purchase experience 2–5 yrs, manufacturing", "definition": "MATCH — 3.5 yrs at an auto-parts manufacturer."}, {"term": "SAP MM", "definition": "MATCH — describes daily PO creation and vendor master work."}, {"term": "Location Ambattur, WFO", "definition": "MATCH — Avadi is a short commute; confirm 6-day week is acceptable."}, {"term": "Tamil (preferred)", "definition": "MATCH."}, {"term": "CTC ≤ 5.5 LPA", "definition": "GAP — expects 5.8; share with hiring manager, no promise to candidate."}, {"term": "Notice ≤ 30 days", "definition": "CLARIFICATION REQUIRED — 45 days, early release possible; confirm in writing."}, {"term": "Decision", "definition": "Shortlist, flagged: CTC and notice need hiring-manager approval."}]}, {"type": "answer", "title": "Model Workflow", "items": [{"term": "Communication", "definition": "\"Your profile fits well. The approved range is up to 5.5 LPA; I''ll share your 5.8 expectation with the team. Please check whether your company can release you within 30 days.\""}, {"term": "Submission", "definition": "Submit with evaluation notes and flagged items."}, {"term": "Scheduling", "definition": "Hiring manager approves; in-person interview Tue 11 am at Ambattur; written confirmation sent and acknowledged; reminder Mon evening."}, {"term": "Follow-up", "definition": "Same-day call to candidate; feedback chased next morning: \"The panel is reviewing; I''ll update you by Thursday.\""}, {"term": "Status update", "definition": "Selected for HR round — communicated only after hiring-manager confirmation; record updated with date/time."}, {"term": "Next action", "definition": "Coordinate HR discussion; track notice-release confirmation."}]}, {"type": "callout", "text": "Every stage depends on the previous record being accurate. A missing note at screening becomes a surprise at offer stage."}]}'::jsonb from public.academy_modules where module_number = 4
